{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C39"],
      "claim": "Testosterone undecanoate, a long-chain ester prodrug structurally analogous to the query's lipophilic ester/lactone design, has a mean absolute oral bioavailability of 6.8 ± 3.3% in humans, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Dimethandrolone undecanoate, another long-chain undecanoate ester prodrug, shows poor and inconsistent oral bioavailability in men, supporting low F for the query's similar lipophilic ester prodrug scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Batimastat, a peptidomimetic with amide/hydroxamate character, has poor oral bioavailability in humans; the query contains an N-formyl-leucine ester moiety, making this low-F evidence transferable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Tetrabenazine, despite high transferability, has very low oral systemic availability (mean 0.049) in patients, supporting low F and illustrating that lipophilic small molecules can undergo extensive first-pass loss.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Felodipine, a lipophilic ester-containing drug, has an absolute oral bioavailability of 15% in humans, below the 20% threshold, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Nimodipine, another ester-containing lipophilic dihydropyridine, has an absolute oral bioavailability of <5% in humans, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Nitrendipine, a close dihydropyridine analogue, has an absolute oral bioavailability of 10.7 ± 4.7% after a 20 mg tablet, below 20%, supporting low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence, including structurally analogous long-chain ester prodrugs and ester-containing lipophilic drugs, shows oral bioavailability below 20%, so the query is predicted to have low absolute oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "The query's exact prodrug activation, lymphatic absorption potential, and first-pass metabolism are not experimentally characterized.",
    "No solubility or permeability data are available for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

